"""Act maps, generated by the ported reference algorithm.

The graph handed to the rest of the simulation keeps its long-standing shape —
nodes keyed by id, each with ``id/row/col/kind/parents/children/fixed`` — but it
is now a direct rendering of ``act_map``'s output rather than a second, hand
written generator. The client already draws whatever the server sends, so no edge
is added or repaired downstream.

Node ids are the *final* coordinates. The reference's pruning and its centring,
spreading and straightening passes all move nodes, so an id captured before those
passes would name the wrong cell; taking it afterwards keeps ids stable across a
reload, which route votes, WingedBoots reachability and quest references all rely on.
"""
from copy import deepcopy

from . import act_map
from ...rng import streams
from .run_setup import act_pools

ACTS = {
    'Overgrowth': {'index': 0, 'rooms': 15, 'weak': 3},
    'Underdocks': {'index': 0, 'rooms': 15, 'weak': 3},
    'Hive': {'index': 1, 'rooms': 14, 'weak': 2},
    'Glory': {'index': 2, 'rooms': 13, 'weak': 2},
}

# ``ModelDb.ActsByIndex``: the pool each act index draws from, in declaration order.
ACT_POOLS = (('Overgrowth', 'Underdocks'), ('Hive',), ('Glory',))

KIND_BY_TYPE = {
    act_map.MapPointType.Monster: 'battle',
    act_map.MapPointType.Elite: 'elite',
    act_map.MapPointType.RestSite: 'rest',
    act_map.MapPointType.Treasure: 'treasure',
    act_map.MapPointType.Shop: 'shop',
    act_map.MapPointType.Unknown: 'unknown',
    act_map.MapPointType.Boss: 'boss',
    act_map.MapPointType.Ancient: 'ancient',
}

# The reference's placement rules, in the public vocabulary. These are the same
# sets ``act_map`` validates against — restated as kinds so callers and tests do
# not have to know about map point types.
ADJACENT_UNIQUE = {KIND_BY_TYPE[t] for t in act_map.PARENT_CHILD_RESTRICTIONS}
SIBLING_UNIQUE = {KIND_BY_TYPE[t] for t in act_map.SIBLING_RESTRICTIONS}


def act_sequence(state):
    """``RunManager.BeginRunLocally``'s act pick, on its own ``act_selection`` stream."""
    with streams.open(state) as rngs:
        rng = rngs.named('act_selection')
        return [rng.next_item(list(pool)) for pool in ACT_POOLS]


_CACHE_LIMIT = 512
_CACHE = {}


def generate_map(state, act, multiplayer=False, *, spoils=False):
    """Build one act's map. Pure in the run seed, so results are cached.

    A map costs about a tenth of a second in Python and nothing else ever draws
    from its stream, which makes caching free of behaviour: the entry records the
    stream's final counter and lanes, so a hit reproduces both the graph and the
    stream state the build would have left behind. The cache is only consulted
    for a pristine stream, so a second build in the same run still rebuilds.
    """
    index = ACTS[act]['index']
    name = 'spoils_map' if spoils else f'act_{index + 1}_map'
    key = (streams.seed_string(state), act, multiplayer, spoils, state.get('ascension',0))

    with streams.open(state) as rngs:
        rng = rngs.named(name)
        if rng.counter == 0:
            cached = _CACHE.get(key)
            if cached is not None:
                graph, counter, lanes = cached
                rng.counter = counter
                rng.random.reinitialise_from_state(lanes)
                return deepcopy(graph)

        if spoils:
            built = act_map.SpoilsActMap(rng, act, multiplayer, ascension=state.get('ascension',0))
        else:
            # ``StandardActMap.CreateFor``: the stream is named for the act number.
            built = act_map.StandardActMap(
                rng, act, multiplayer,
                replace_treasure_with_elites=False, has_second_boss=index==2 and state.get('ascension',0)>=10,
                ascension=state.get('ascension',0))

        graph = to_graph(built, act, index, spoils=spoils)
        saved = rng.to_serializable()
        if len(_CACHE) >= _CACHE_LIMIT:
            _CACHE.clear()
        _CACHE[key] = (graph, saved['counter'],
                       [saved['s0'], saved['s1'], saved['s2'], saved['s3']])
    return deepcopy(graph)


def golden_path(state, act):
    """``GoldenPathActMap`` — fixed route, and it consumes no randomness at all."""
    index = ACTS[act]['index']
    return to_graph(act_map.GoldenPathActMap(len(state.get('players', {})) > 1),
                    act, index, spoils=False, golden=True)


def to_graph(built, act, index, *, spoils, golden=False):
    nodes = {}
    for point in built.all_nodes_with_boss():
        ident = f'{index}:{point.row}:{point.col}'
        nodes[ident] = {
            'id': ident, 'row': point.row, 'col': point.col,
            'kind': KIND_BY_TYPE[point.type],
            'parents': [], 'children': [],
            # ``fixed`` means the type was pinned by the generator, not chosen.
            'fixed': not point.can_be_modified,
        }

    for point in built.all_nodes_with_boss():
        parent = nodes[f'{index}:{point.row}:{point.col}']
        for child in point.children:
            child_id = f'{index}:{child.row}:{child.col}'
            parent['children'].append(child_id)
            nodes[child_id]['parents'].append(parent['id'])

    start = f'{index}:{built.starting.row}:{built.starting.col}'
    boss = f'{index}:{built.boss.row}:{built.boss.col}'
    first_boss=boss
    if built.second_boss is not None:boss=f'{index}:{built.second_boss.row}:{built.second_boss.col}'
    graph = {'firstBoss':first_boss,'act': act, 'rooms': built.get_row_count() - 1, 'start': start, 'boss': boss,
             'spoils': spoils, 'quotas': {}, 'nodes': nodes}
    if golden:
        graph['golden'] = True
    return graph


def reachable(graph, current):
    return [graph['nodes'][ident] for ident in graph['nodes'][current]['children']]
